#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


POLAR_SANDBOX_DASHBOARD="https://sandbox.polar.sh"
POLAR_SANDBOX_API="https://sandbox-api.polar.sh/v1"
UUID_PATTERN='^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

# set_preview_secret NAME VALUE pose un secret de l'environnement GitHub `preview`,
# d'où preview.yml tire les secrets qu'il passe au Worker dezyn-api-preview.
set_preview_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" --env preview >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name (preview)")
      printf '  %s✓ set%s GitHub secret %s (environnement preview)\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("secret $name de l'environnement preview : gh secret set $name --env preview")
  warn "secret $name non posé : gh n'est pas prêt"
}

# set_preview_var NAME VALUE pose une variable de l'environnement GitHub `preview`.
set_preview_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --env preview --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s (environnement preview)\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("variable $name de l'environnement preview : gh variable set $name --env preview --body '$value'")
  warn "variable $name non posée : gh n'est pas prêt"
}

# polar_get PATH appelle l'API sandbox de Polar avec le jeton capturé.
polar_get() {
  curl --silent --show-error --max-time 15 \
    --header "Authorization: Bearer $POLAR_ACCESS_TOKEN" \
    "$POLAR_SANDBOX_API$1"
}

run_wizard() {

cd "$(dirname "$0")/../.."

TOTAL_STAGES=7

banner "Polar : environnement sandbox de dezyn"

stage "Compte et organisation sandbox"
say "Le sandbox de Polar est séparé de la production : compte, organisation et jetons à part."
open_url "$POLAR_SANDBOX_DASHBOARD/start"
step "Créer un compte dédié au sandbox (un compte de production ne s'y connecte pas)."
step "Créer l'organisation, par exemple « dezyn sandbox »."
note "Le sandbox n'envoie les emails clients (confirmations, relances) qu'aux membres"
note "de l'organisation : Settings → Members. Les adresses en +test sont acceptées."
note "Carte de test au paiement : 4242 4242 4242 4242, date future, CVC quelconque."
pause "Organisation créée ? Entrée pour continuer"

stage "Devise et traitement des taxes"
say "Le plan Team se vend 34,99 € HT : prix en euros, taxe ajoutée au checkout."
open_url "$POLAR_SANDBOX_DASHBOARD/dashboard"
step "Ouvrir les Settings de l'organisation, section Payments."
step "Default tax behavior : choisir « Exclusive » (enregistré automatiquement)."
step "Devise de paiement par défaut de l'organisation : choisir EUR."
note "Un produit exige un prix dans la devise par défaut : sans EUR par défaut,"
note "le formulaire du produit demande un prix dans une autre devise."
note "Polar calcule, collecte et reverse la taxe de chaque pays (Merchant of Record)."
pause "Exclusive et EUR réglés ? Entrée pour continuer"

stage "Produit Team"
open_url "$POLAR_SANDBOX_DASHBOARD/dashboard"
step "Ouvrir Products, puis créer un nouveau produit."
step "Nom : Team."
step "Type : abonnement (recurring), facturé tous les mois (monthly)."
note "Le cycle de facturation ne change plus après la création."
step "Prix : Fixed price, 34.99, en EUR."
step "Traitement des taxes du prix, s'il est proposé : Exclusive, ou celui de l'organisation."
step "N'ajouter aucun bénéfice (benefit), puis enregistrer le produit."
pause "Produit Team créé ? Entrée pour continuer"

stage "Jeton d'accès d'organisation"
open_url "$POLAR_SANDBOX_DASHBOARD/dashboard"
step "Settings → Access Tokens → Create token."
step "Nom : dezyn-preview. Expiration : la plus longue proposée."
step "Cocher exactement ces scopes :"
note "    checkouts:write          créer le checkout d'un espace"
note "    customer_sessions:write  ouvrir le portail client"
note "    customers:read           relire le client Polar d'un utilisateur"
note "    customers:write          créer le client Polar d'un utilisateur"
note "    subscriptions:read       lire les abonnements"
note "    subscriptions:write      résilier en fin de période au départ du payeur"
note "    products:read            lire le produit Team"
note "Les webhooks se vérifient par leur secret : aucun scope webhooks n'est requis."
step "Créer le jeton, puis le copier tout de suite."
ask_secret POLAR_ACCESS_TOKEN "Coller le jeton d'accès :"
write_env POLAR_ACCESS_TOKEN "$POLAR_ACCESS_TOKEN"
write_env POLAR_SERVER sandbox
set_preview_secret POLAR_ACCESS_TOKEN "$POLAR_ACCESS_TOKEN"
set_preview_var POLAR_SERVER sandbox
pause

stage "Identifiant du produit Team"
say "Produits de l'organisation sandbox, lus avec le jeton :"
if products=$(polar_get "/products/?is_archived=false") &&
  jq -e '.items' >/dev/null 2>&1 <<< "$products"; then
  jq -r '.items[] | "    \(.id)  \(.name)"' <<< "$products"
else
  warn "lecture impossible : copier l'identifiant (UUID) depuis la page du produit Team."
fi
ask POLAR_TEAM_PRODUCT_ID "Identifiant du produit Team :"
until [[ "$POLAR_TEAM_PRODUCT_ID" =~ $UUID_PATTERN ]]; do
  warn "un identifiant de produit est un UUID en minuscules, par exemple 0b1c2d3e-…"
  ask POLAR_TEAM_PRODUCT_ID "Identifiant du produit Team :"
done
write_env POLAR_TEAM_PRODUCT_ID "$POLAR_TEAM_PRODUCT_ID"
set_preview_var POLAR_TEAM_PRODUCT_ID "$POLAR_TEAM_PRODUCT_ID"
pause

stage "Webhook vers l'API de preview"
say "L'API reçoit les webhooks de Polar sur sa route /webhooks/polar (ADR 0050)."
say "Chaque preview a sa propre base : le webhook vise la preview de la PR qui teste le paiement."
ask POLAR_WEBHOOK_PR "Numéro de la PR dont la preview reçoit les webhooks :"
until [[ "$POLAR_WEBHOOK_PR" =~ ^[1-9][0-9]*$ ]]; do
  warn "un numéro de PR, par exemple 346"
  ask POLAR_WEBHOOK_PR "Numéro de la PR dont la preview reçoit les webhooks :"
done
webhook_url="https://pr-$POLAR_WEBHOOK_PR-api-preview.dezyn.dev/webhooks/polar"
open_url "$POLAR_SANDBOX_DASHBOARD/dashboard"
step "Settings → Webhooks → Add Endpoint."
step "URL : $webhook_url"
step "Format : Raw."
step "Version d'API : 2027-01."
step "Secret : le laisser générer par Polar."
step "Événements : subscription.created, subscription.updated, subscription.active,"
step "subscription.canceled, subscription.uncanceled, subscription.revoked, subscription.past_due."
step "Créer l'endpoint, puis copier son secret."
note "Pour une autre PR, modifier l'URL de cet endpoint : le secret reste le même."
ask_secret POLAR_WEBHOOK_SECRET "Coller le secret du webhook :"
write_env POLAR_WEBHOOK_SECRET "$POLAR_WEBHOOK_SECRET"
set_preview_secret POLAR_WEBHOOK_SECRET "$POLAR_WEBHOOK_SECRET"
pause

stage "Vérification"
say "Lecture du produit Team par l'API sandbox avec le jeton :"
response=$(mktemp)
status=$(curl --silent --show-error --max-time 15 --output "$response" --write-out '%{http_code}' \
  --header "Authorization: Bearer $POLAR_ACCESS_TOKEN" \
  "$POLAR_SANDBOX_API/products/$POLAR_TEAM_PRODUCT_ID" || true)
if [[ "$status" == "200" ]]; then
  jq -r '"    \(.name) · \(if .is_recurring then "abonnement \(.recurring_interval)" else "paiement unique" end)",
    (.prices[] | "    \(.amount_type) \(.price_amount // "-") \(.price_currency // "")")' "$response" ||
    cat "$response"
  printf '  %s✓ produit lisible%s\n' "$GREEN" "$RESET"
  note "Attendu : abonnement month, et un prix fixed 3499 eur (montant en centimes)."
else
  SKIPPED+=("lecture du produit $POLAR_TEAM_PRODUCT_ID : HTTP $status")
  warn "HTTP $status : vérifier le jeton, son scope products:read et l'identifiant du produit."
fi
rm -f "$response"
pause

finish
}

run_wizard "$@"; exit
